CREATE TABLE payment_milestones(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`booking_id` BIGINT  NOT NULL,`milestone_type` varchar(50)  NOT NULL,`amount` DECIMAL(10,2)  NOT NULL,`due_date` timestamp  NOT NULL,`paid_date` timestamp  NULL,`status` varchar(50)  NOT NULL DEFAULT 'pending',`payment_method` varchar(100)  NULL,`transaction_id` varchar(255)  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;